// The Software & IT solutions portfolio: 6 categories, 64 showcased solutions and industry categories.
// `solutions-index.json` is the slim built-in list (cards); the long text of each solution is in `solutions.json`, which is only loaded with a detail page.
// Both are generated by backend/scripts/build_solutions.py (and seeded into the database by `python -m app.cli migrate-content`, after which the Admin Panel is the source).
import index from './solutions-index.json'

export const builtinIndex = index

/** Availability. Only "available" means a LAX360 product exists; everything else is described as built to order or as not launched. */
/** Responsive attributes for a solution image: the built-in previews have an 800 px variant (-800.webp) next to the 1600 px file; uploaded images are used as they are. */
export function imgSet(src) {
  const m = /^(\/assets\/solutions\/.+)\.webp$/.exec(src || '')
  return m ? { src, srcSet: `${m[1]}-800.webp 800w, ${src} 1600w` } : { src }
}

export const STATUSES = {
  available: { label: 'Solution', tone: 'green', note: 'LAX360 provides this solution and can customise it to your business requirements.' },
  custom: { label: 'Solution', tone: 'sky', note: 'LAX360 provides this solution and can customise it to your business requirements.' },
  under_development: { label: 'Under Development', tone: 'violet', note: 'Under development. Not available to order yet; no launch date has been announced.' },
  coming_soon: { label: 'Coming Soon', tone: 'amber', note: 'Coming soon. Register your interest and we will let you know.' },
  live: { label: 'Live', tone: 'green', note: 'LAX360 provides this solution and can customise it to your business requirements.' },
  demo_available: { label: 'Demo Available', tone: 'green', note: 'LAX360 provides this solution and can customise it to your business requirements.' },
  temporarily_unavailable: { label: 'Temporarily Unavailable', tone: 'amber', note: 'Temporarily unavailable. Register your interest and we will tell you when it is back.' },
}
export const statusOf = (s) => STATUSES[s] || STATUSES.custom

export const solutionHref = (s) => `/solutions/${s.slug}`

/** The call-to-action buttons that fit a solution's real availability. */
export function actionsFor(s) {
  const q = (extra = '') => `/contact?type=product&solution=${encodeURIComponent(s.slug)}${extra}`
  if (s.status === 'under_development' || s.status === 'coming_soon' || s.status === 'temporarily_unavailable') return { primary: { label: 'Register Your Interest', to: q('&intent=interest') }, secondary: { label: 'Discuss Your Requirements', to: q('&intent=discuss') } }
  return { primary: { label: 'Enquire Now', to: q('&intent=enquire') }, secondary: { label: 'Discuss Customisation', to: q('&intent=discuss') } }
}

